require 'db_connect.php';

// Função para criar uma cláusula IN segura
function createInClause($column, $values, $conn, &$types, &$params) {
    if (empty($values)) {
        return "1"; // Sempre verdadeiro se não houver valores
    }
    $placeholders = implode(',', array_fill(0, count($values), '?'));
    $types .= str_repeat('s', count($values));
    foreach ($values as $value) {
        $params[] = $value;
    }
    return "$column IN ($placeholders)";
}

// Buscar GREs
$gres = $conn->query("SELECT DISTINCT gre FROM turmas WHERE gre LIKE 'GRE%' ORDER BY gre");

