    // Criar cláusula IN para GREs
    $types = '';
    $params = [];
    $gre_clause = createInClause('gre', $selected_gres, $conn, $types, $params);
    $stmt = $conn->prepare("SELECT DISTINCT escola FROM turmas WHERE $gre_clause ORDER BY escola");
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }
    if ($gre_clause !== "1") {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $escolas = $stmt->get_result();
    $stmt->close();
}

